import React from "react";
import { BoldReport } from "../components/BoldReport";

export default function BoldReportsPage()
{
  return (
    <div>
      <h2>Team Event Report</h2>
      <BoldReport
        apiUrl="https://localhost:59497/api/reports/event-report"
        reportName="event_report.rdl"
        tenantId="00000000-0000-0000-0000-000000000000" // replace with your tenant
      />
    </div>
  );
};
